using System;
using System.Linq;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering;

// Separate editable art studies. Source gameplay scenes are read only.
public static class CollaborationArtBuilder
{
 static System.Collections.Generic.Dictionary<GameObject,bool> activeStates=new System.Collections.Generic.Dictionary<GameObject,bool>();
 static void Mute(Scene s){foreach(var r in s.GetRootGameObjects()){if(!activeStates.ContainsKey(r))activeStates[r]=r.activeSelf;r.SetActive(false);}}
 static void Restore(Scene s){foreach(var r in s.GetRootGameObjects())if(activeStates.ContainsKey(r))r.SetActive(activeStates[r]);}
 static Scene scene; static Material steel,dark,concrete,paint,rust,glow,red,coat,skin;
 static Vector3 V(float x,float y,float z){return new Vector3(x,y,z);}
 static Material M(string n){return AssetDatabase.LoadAssetAtPath<Material>("Assets/RecoilArtTest/Materials/"+n+".mat");}
 static Transform G(string n,Transform p=null){var g=new GameObject(n);SceneManager.MoveGameObjectToScene(g,scene);if(p)g.transform.SetParent(p,false);return g.transform;}
 static GameObject B(string n,Vector3 pos,Vector3 size,Material m,Transform p,PrimitiveType kind=PrimitiveType.Cube){var g=GameObject.CreatePrimitive(kind);g.name=n;SceneManager.MoveGameObjectToScene(g,scene);g.transform.SetParent(p,false);g.transform.localPosition=pos;g.transform.localScale=size;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=m;return g;}
 static GameObject R(string n,Vector3 a,Vector3 b,float radius,Material m,Transform p){var g=B(n,(a+b)*.5f,V(radius*2,Vector3.Distance(a,b)*.5f,radius*2),m,p,PrimitiveType.Cylinder);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);return g;}
 static void Figure(string n,float x,float y,Transform p,bool monster=false){var g=G(n,p);g.localPosition=V(x,y,0);B("Coat",V(0,.98f,0),V(.39f,.41f,.28f),monster?dark:coat,g,PrimitiveType.Capsule);B("Head",V(0,1.52f,0),V(.24f,.29f,.25f),skin,g,PrimitiveType.Sphere);R("Leg",V(-.1f,.7f,0),V(-.14f,.05f,0),.055f,dark,g);R("Leg",V(.1f,.7f,0),V(.17f,.05f,0),.055f,dark,g);R("Arm",V(-.17f,1.2f,0),V(-.24f,.62f,0),.05f,monster?skin:coat,g);R("Arm",V(.17f,1.2f,0),V(.22f,.65f,0),.05f,monster?skin:coat,g);if(!monster)B("Satchel",V(.2f,.85f,0),V(.16f,.28f,.34f),rust,g);}
 static void Lamp(string n,Vector3 pos,float strength,Transform p,bool emergency=false){var g=G(n,p);g.localPosition=pos;B("Housing",Vector3.zero,V(.8f,.15f,.4f),dark,g);var bulb=B("Lamp glass",V(0,-.09f,0),V(.58f,.05f,.3f),emergency?red:glow,g);var t=G("Light",g);t.localPosition=V(0,-.14f,0);t.localRotation=Quaternion.Euler(90,0,0);var l=t.gameObject.AddComponent<Light>();l.type=LightType.Spot;l.range=12;l.spotAngle=85;l.intensity=strength;l.color=emergency?new Color(1,.04f,.015f):new Color(.65f,.78f,.8f);l.shadows=LightShadows.Soft;if(emergency){var pulse=g.gameObject.AddComponent<FactoryArtLamp>();pulse.source=l;pulse.luminousSurface=bulb.GetComponent<Renderer>();pulse.peakIntensity=strength;}}
 static Camera CameraAt(Vector3 pos,Vector3 look,float fov){var c=G("Art Camera").gameObject.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(look);c.fieldOfView=fov;c.nearClipPlane=.1f;c.farClipPlane=160;c.allowHDR=true;c.backgroundColor=new Color(.018f,.032f,.041f);c.clearFlags=CameraClearFlags.SolidColor;var nav=c.gameObject.AddComponent<FactoryArtCamera>();nav.filmGrade=M("FilmGrade");return c;}
 static void Capture(Camera c,string name,Vector3 pos,Vector3 look,float fov){foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=30;c.cullingMask=1<<30;c.transform.position=pos;c.transform.LookAt(look);c.fieldOfView=fov;var rt=new RenderTexture(1920,1080,24,RenderTextureFormat.ARGB32);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1920,1080,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1920,1080),0,0);tex.Apply();Directory.CreateDirectory("output/presentations/atmosphere");File.WriteAllBytes("output/presentations/atmosphere/"+name+".png",tex.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}
 static Scene Open(string p){var loaded=SceneManager.GetSceneByPath(p);return loaded.isLoaded?loaded:EditorSceneManager.OpenScene(p,OpenSceneMode.Additive);}
 static void Init(){var grade=M("FilmGrade");grade.SetFloat("_Exposure",2.5f);EditorUtility.SetDirty(grade);steel=M("Weathered steel");dark=M("Silhouette metal");concrete=M("Concrete");paint=M("Old green paint");rust=M("Oxidized metal");glow=M("Cold luminous glass");red=M("Emergency red glass");coat=M("Player ochre coat");skin=M("Ashen skin");}
 static void Indoor(){
  var source=Open("Assets/Scenes/RecoilFactoryInterior.unity");var colliders=source.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<BoxCollider2D>()).Where(c=>!c.isTrigger).Select(c=>new{c.name,b=c.bounds}).ToArray();
  var machines=source.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<EquipmentHandhold>()).Select(h=>new{p=h.transform.parent.position,scale=h.transform.parent.lossyScale,hold=h.Position}).ToArray();
  var chains=source.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<SwingingChain>()).Select(c=>new{p=c.transform.position,c.length}).ToArray();
  var enemies=source.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<RampagerController>()).Select(e=>e.transform.position).ToArray();
  Mute(source);
  string path="Assets/Scenes/RecoilFactoryArt3D.unity";Directory.CreateDirectory("Backups/ArtStudies");if(!File.Exists("Backups/ArtStudies/RecoilFactoryArt3D_before_GSMD_20261012.unity"))File.Copy(path,"Backups/ArtStudies/RecoilFactoryArt3D_before_GSMD_20261012.unity");scene=Open(path);SceneManager.SetActiveScene(scene);
  var old=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>()).ToArray();
  foreach(var t in old.Where(t=>t.name=="Maintenance Platform"||t.name=="Platform support"||t.name=="Platform edge grating"))if(t)UnityEngine.Object.DestroyImmediate(t.gameObject);
  float ceiling=colliders.Where(c=>c.name.ToLower().Contains("ceiling")).Select(c=>c.b.min.y).DefaultIfEmpty(7.3f).First();
  foreach(var t in old){if(!t)continue;if(t.name=="Low ceiling")t.position=V(15,ceiling+.2f,4);if(t.name=="Roof cross beam")t.position=V(t.position.x,ceiling-.14f,4);if(t.name=="Rear concrete wall"||t.name=="Left end wall"||t.name=="Right end wall"||t.name=="Rear pilaster"){var s=t.localScale;s.y=ceiling;t.localScale=s;var p=t.position;p.y=ceiling/2;t.position=p;}if(t.name.StartsWith("Cold fixture")||t.name=="Emergency fixture"){var p=t.position;p.y=ceiling-.3f;t.position=p;}}
  var previous=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="06 Current layout additions");if(previous)UnityEngine.Object.DestroyImmediate(previous);var additions=G("06 Current layout additions");
  foreach(var c in colliders.Where(c=>c.name=="Maintenance Platform")){B("Maintenance Platform - saved layout",V(c.b.center.x,c.b.center.y,1),V(c.b.size.x,c.b.size.y,3),steel,additions);for(int k=-1;k<=1;k+=2)B("Platform leg",V(c.b.center.x+k*c.b.size.x*.4f,c.b.min.y/2,1.4f),V(.17f,c.b.min.y,.17f),rust,additions);}
  foreach(var m in machines){var g=G("Large riveted machinery - saved layout",additions);g.position=V(m.p.x,m.p.y,1.1f);g.localScale=m.scale;B("Machine",V(0,2.25f,0),V(2.8f,4.5f,1.6f),steel,g);B("Panel",V(-.78f,2.5f,-.83f),V(.85f,3.15f,.08f),paint,g);for(int side=-1;side<=1;side+=2)for(int k=0;k<6;k++)B("Rivet",V(side*1.23f,.52f+k*.69f,-.87f),V(.1f,.1f,.06f),rust,g,PrimitiveType.Sphere);R("Grab handle",V(-.85f,3.22f,-1),V(-.85f,3.98f,-1),.065f,rust,g);R("Upper handle bracket",V(-.85f,3.98f,-1),V(-.6f,3.98f,-.82f),.04f,rust,g);R("Lower handle bracket",V(-.85f,3.22f,-1),V(-.6f,3.22f,-.82f),.04f,rust,g);for(int k=0;k<6;k++)B("Cooling vent",V(.65f,1.3f+k*.22f,-.84f),V(.75f,.055f,.02f),dark,g);}
  foreach(var c in chains){var g=G("Suspended chain - saved layout",additions);for(float y=.1f;y<c.length;y+=.13f){var link=B("Iron link",V(c.p.x,c.p.y-y,0),V(.09f,.13f,.065f),rust,g,PrimitiveType.Capsule);link.transform.localRotation=Quaternion.Euler(0,(int)(y/.13f)%2*90,0);}R("Overhead chain support",V(c.p.x-.3f,c.p.y,0),V(c.p.x+.3f,c.p.y,0),.06f,steel,g);}
  foreach(var r in scene.GetRootGameObjects().Where(g=>g.name.StartsWith("05 Scale")))UnityEngine.Object.DestroyImmediate(r);var cast=G("05 Scale reference characters - current layout");Figure("Dun - art reference",3,0,cast);foreach(var e in enemies)Figure("Sleeping Rampager - art reference",e.x,Mathf.Max(0,e.y-.8f),cast,true);
  RenderSettings.ambientLight=new Color(.13f,.16f,.18f);var cam=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>()).First();Capture(cam,"factory-entry",V(11,3.1f,-17),V(11,3,3),40);Capture(cam,"factory-machinery",V(20,3.3f,-17),V(20,3,3),40);cam.transform.position=V(15,3.3f,-18);cam.transform.LookAt(V(15,3.2f,3));EditorSceneManager.SaveScene(scene,path);EditorSceneManager.CloseScene(scene,true);Restore(source);
 }
 static void Outdoor(){
  var source=Open("Assets/Scenes/RecoilPrototype.unity");var ts=source.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>()).ToArray();var door=source.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<RecoilDoor>()).FirstOrDefault(d=>d.destinationScene.Contains("ServiceStore"));float storeX=door?door.transform.position.x:-22.6f;var fuel=source.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<FuelPumpInteraction>()).Select(p=>p.transform.position.x).ToArray();float pumpX=fuel.Length>0?fuel.Average():storeX-13;var tower=ts.FirstOrDefault(t=>t.name=="Broadcast Tower");float towerX=tower?tower.position.x:5.97f;
  Mute(source);scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(scene);RenderSettings.skybox=null;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.24f,.29f,.32f);RenderSettings.fog=true;RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogColor=new Color(.035f,.055f,.067f);RenderSettings.fogStartDistance=35;RenderSettings.fogEndDistance=100;
  var structures=G("01 Station - current gameplay positions");B("Road and forecourt",V(-10,-.2f,10),V(115,.4f,35),concrete,structures);var store=G("Service store",structures);store.position=V(storeX+2,0,3.5f);B("Store rear wall",V(0,2.1f,3),V(10,4.2f,.4f),concrete,store);B("Flat roof",V(0,4.35f,0),V(10.7f,.35f,6.8f),steel,store);B("Skylight",V(0,4.58f,0),V(1.8f,.14f,1.4f),glow,store);B("Front fascia",V(0,3.65f,-3.1f),V(10,.5f,.3f),paint,store);for(int i=-1;i<=1;i+=2){B("Shop wall",V(i*4.6f,1.8f,-2.9f),V(.8f,3.6f,.3f),concrete,store);B("Dark glazing",V(i*2.7f,1.8f,-2.92f),V(3.1f,2.6f,.08f),dark,store);for(int k=-1;k<=1;k++)B("Window mullion",V(i*2.7f+k,1.8f,-3),V(.065f,2.8f,.12f),steel,store);}B("Entrance",V(-2,1.4f,-3.05f),V(1.15f,2.8f,.12f),paint,store);Lamp("Store porch lamp",V(-2,3.3f,-3.3f),2,store);
  var canopy=G("Four-nozzle fuel island",structures);canopy.position=V(pumpX,0,1.5f);B("Canopy",V(0,4.1f,0),V(8.5f,.35f,6),paint,canopy);for(int i=-1;i<=1;i+=2)R("Support",V(i*3.5f,0,1.5f),V(i*3.5f,4,1.5f),.09f,steel,canopy);for(int i=-1;i<=1;i+=2){var p=G("Pump with two nozzles",canopy);p.localPosition=V(i*1.8f,0,0);B("Pump base",V(0,.3f,0),V(.9f,.6f,.7f),steel,p);B("Pump housing",V(0,1.2f,0),V(.85f,1.3f,.5f),paint,p);B("Out of order display",V(0,1.5f,-.27f),V(.55f,.25f,.04f),red,p);for(int k=-1;k<=1;k+=2){R("Hose",V(k*.49f,1.5f,0),V(k*.65f,.4f,0),.025f,dark,p);R("Nozzle",V(k*.5f,1.4f,-.12f),V(k*.5f,1.08f,-.12f),.04f,steel,p);}}Lamp("Fuel canopy lamp",V(0,3.88f,0),3,canopy);
  var depth=G("02 Town and industrial depth");for(int i=0;i<9;i++){float x=-40+i*10;float h=5+(i%3)*2;B("Distant industrial building",V(x,h/2,35+(i%2)*9),V(7,h,8),dark,depth);R("Chimney",V(x+2,h,38),V(x+2,h+8,38),.5f,steel,depth);}var towerRoot=G("Alarm tower - saved X",depth);towerRoot.position=V(towerX,0,5);for(int i=-1;i<=1;i+=2)R("Tower leg",V(i*1.4f,0,0),V(i*.8f,24,0),.09f,steel,towerRoot);for(int y=3;y<24;y+=3){R("Diagonal brace",V(-1.2f,y,0),V(1.2f,y+3,0),.045f,steel,towerRoot);B("Tower deck",V(0,y,0),V(3,.14f,2),rust,towerRoot);}for(int x=-1;x<=1;x++)for(int y=0;y<2;y++)B("Alarm horn",V(x*.85f,24+y*.9f,-.3f),V(.65f,.55f,1),steel,towerRoot);Lamp("Tower red beacon",V(0,26,0),2,towerRoot,true);
  var car=G("Dun's stranded car",structures);car.position=V(pumpX-9,0,-.5f);B("Car body",V(0,.75f,0),V(3.8f,.8f,1.7f),paint,car);B("Cabin",V(0,1.35f,0),V(2.2f,.6f,1.5f),dark,car);for(int side=-1;side<=1;side+=2){var wheel=B("Wheel",V(side*1.2f,.37f,-.88f),V(.7f,.16f,.7f),dark,car,PrimitiveType.Cylinder);wheel.transform.localRotation=Quaternion.Euler(90,0,0);}
  var cast=G("03 Art scale references");Figure("Dun",pumpX-3,0,cast);float enemyX=-7.4f;Figure("Still figure below failing lamp",enemyX,0,cast,true);var pole=G("Unstable street lamp",structures);pole.position=V(enemyX,0,0);R("Pole",Vector3.zero,V(0,5,0),.075f,steel,pole);R("Arm",V(0,5,0),V(-.8f,5,0),.05f,steel,pole);Lamp("Failing lamp",V(-.8f,5,0),2.7f,pole);var fill=G("Moonlight");fill.localRotation=Quaternion.Euler(40,-35,0);var l=fill.gameObject.AddComponent<Light>();l.type=LightType.Directional;l.color=new Color(.52f,.65f,.75f);l.intensity=.85f;l.shadows=LightShadows.Soft;
  var cam=CameraAt(V(storeX-7,2.8f,-24),V(storeX-7,2.3f,3),45);Capture(cam,"station-exterior",V(storeX-7,2.8f,-24),V(storeX-7,2.3f,3),45);Capture(cam,"town-approach",V(-4,6,-37),V(-4,6,6),45);cam.transform.position=V(storeX-7,2.8f,-24);cam.transform.LookAt(V(storeX-7,2.3f,3));EditorSceneManager.SaveScene(scene,"Assets/Scenes/RecoilOutdoorArt3D.unity");EditorSceneManager.CloseScene(scene,true);Restore(source);
 }
 [MenuItem("Recoil/Art Test/Update GSMD Studies and Capture")]
 public static void BuildAndCapture(){if(EditorApplication.isPlaying)throw new Exception("Exit Play first");var original=SceneManager.GetActiveScene();var loaded=Enumerable.Range(0,SceneManager.sceneCount).Select(i=>SceneManager.GetSceneAt(i).path).ToArray();Init();Indoor();Outdoor();foreach(var path in new[]{"Assets/Scenes/RecoilFactoryInterior.unity","Assets/Scenes/RecoilPrototype.unity"}){var s=SceneManager.GetSceneByPath(path);if(s.isLoaded&&!loaded.Contains(path))EditorSceneManager.CloseScene(s,true);}SceneManager.SetActiveScene(original);AssetDatabase.SaveAssets();Debug.Log("GSMD_ART_CAPTURE_COMPLETE");}
}
